package com.xiangjiaojiaozhu.englishclock;
import android.app.*; import android.content.*; import android.graphics.*; import android.net.*; import android.os.*; import android.provider.Settings; import android.text.*; import android.text.style.*; import android.view.*; import android.widget.*; import java.io.*; import java.util.*; import java.util.regex.*;

public class MainActivity extends Activity {
  Db db; LinearLayout root,content,nav; int blue=Color.rgb(21,101,192),pad; Handler handler=new Handler(); long timerEnd; boolean timerRun;
  public void onCreate(Bundle b){super.onCreate(b); db=new Db(this);pad=dp(14); requestNotice(); buildShell(); showHome(); handleShare(getIntent());}
  int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);} TextView tv(String s,int sp,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(c);v.setPadding(dp(8),dp(8),dp(8),dp(8));return v;}
  Button btn(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setOnClickListener(l);return b;}
  void buildShell(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL); TextView bar=tv("English Clock · 英语学习",20,Color.WHITE);bar.setBackgroundColor(blue);bar.setGravity(Gravity.CENTER);bar.setPadding(8,pad,8,pad);root.addView(bar,new LinearLayout.LayoutParams(-1,-2));content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);String[] ns={"文章","生词","专注","提醒"};for(int i=0;i<4;i++){final int x=i;Button b=btn(ns[i],v->{if(x==0)showHome();if(x==1)showVocab();if(x==2)showFocus();if(x==3)showAlarm();});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav);setContentView(root);}
  void clear(String title){content.removeAllViews();TextView h=tv(title,23,Color.BLACK);h.setTypeface(null,Typeface.BOLD);content.addView(h);}
  void showHome(){clear("我的英语文章");LinearLayout row=new LinearLayout(this);row.addView(btn("粘贴新文章",v->pasteDialog()),new LinearLayout.LayoutParams(0,-2,1));row.addView(btn("导入 TXT",v->pickTxt()),new LinearLayout.LayoutParams(0,-2,1));content.addView(row);ArrayList<String[]> as=db.articles();if(as.isEmpty())content.addView(tv("还没有文章。可以粘贴正文，或从文件管理选择 TXT。",17,Color.DKGRAY));for(String[] a:as){Button x=btn(a[1]+"\n"+a[3],v->readArticle(a));x.setGravity(Gravity.LEFT);content.addView(x,new LinearLayout.LayoutParams(-1,-2));}}
  void pasteDialog(){final EditText title=new EditText(this);title.setHint("标题");final EditText body=new EditText(this);body.setHint("在这里粘贴英文文章");body.setMinLines(8);LinearLayout p=new LinearLayout(this);p.setPadding(pad,pad,pad,pad);p.setOrientation(LinearLayout.VERTICAL);p.addView(title);p.addView(body);new AlertDialog.Builder(this).setTitle("粘贴新文章").setView(p).setPositiveButton("保存",(d,w)->{String s=body.getText().toString().trim();if(s.length()>0){db.addArticle(title.getText().toString().trim().length()>0?title.getText().toString():"文章 "+Db.today(),s);showHome();}}).setNegativeButton("取消",null).show();}
  void pickTxt(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("text/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,7);} protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==7&&c==RESULT_OK&&d!=null)try{Uri u=d.getData();BufferedReader br=new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(u)));StringBuilder s=new StringBuilder();String l;while((l=br.readLine())!=null)s.append(l).append('\n');db.addArticle("导入文章 "+Db.today(),s.toString());showHome();}catch(Exception e){Toast.makeText(this,"导入失败: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
  void handleShare(Intent i){if(Intent.ACTION_SEND.equals(i.getAction())&&"text/plain".equals(i.getType())){String s=i.getStringExtra(Intent.EXTRA_TEXT);if(s!=null&&s.length()>10){db.addArticle(i.getStringExtra(Intent.EXTRA_SUBJECT)==null?"分享的文章":i.getStringExtra(Intent.EXTRA_SUBJECT),s);showHome();}}}
  void readArticle(String[] a){clear(a[1]);TextView tip=tv("点击英文单词即可加入/取消生词。黄色表示已加入。",15,Color.DKGRAY);content.addView(tip);TextView article=tv("",20,Color.rgb(30,30,30));article.setLineSpacing(0,1.45f);SpannableString sp=new SpannableString(a[2]);Matcher m=Pattern.compile("[A-Za-z]+(?:['’-][A-Za-z]+)*").matcher(a[2]);while(m.find()){final String w=m.group();int st=m.start(),en=m.end();if(db.hasWord(w))sp.setSpan(new BackgroundColorSpan(Color.rgb(255,224,138)),st,en,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);sp.setSpan(new ClickableSpan(){public void onClick(View v){db.toggleWord(w,sentence(a[2],w),a[1]);Toast.makeText(MainActivity.this,db.hasWord(w)?"已加入: "+w:"已取消: "+w,Toast.LENGTH_SHORT).show();readArticle(a);}public void updateDrawState(android.text.TextPaint p){super.updateDrawState(p);p.setColor(Color.rgb(25,25,25));p.setUnderlineText(false);}},st,en,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}article.setText(sp);article.setMovementMethod(android.text.method.LinkMovementMethod.getInstance());content.addView(article);content.addView(btn("删除这篇文章",v->new AlertDialog.Builder(this).setMessage("删除这篇文章？生词会保留。").setPositiveButton("删除",(d,w)->{db.deleteArticle(Long.parseLong(a[0]));showHome();}).setNegativeButton("取消",null).show()));}
  String sentence(String t,String word){int i=t.toLowerCase().indexOf(word.toLowerCase());if(i<0)return"";int s=i,e=i+word.length();while(s>0&&".!?\n".indexOf(t.charAt(s-1))<0)s--;while(e<t.length()&&".!?\n".indexOf(t.charAt(e))<0)e++;return t.substring(s,Math.min(t.length(),e+1)).trim();}
  void showVocab(){clear("生词本");EditText q=new EditText(this);q.setHint("搜索单词或中文");content.addView(q);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list);Runnable draw=()->{list.removeAllViews();for(String[] v:db.vocab(q.getText().toString())){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(pad,pad,pad,pad);card.setBackgroundColor(v[6].equals("1")?Color.rgb(238,238,238):Color.rgb(232,245,253));TextView w=tv(v[1]+(v[6].equals("1")?"  ✓":""),22,Color.BLACK);w.setTypeface(null,Typeface.BOLD);card.addView(w);card.addView(tv(v[2].length()>0?v[2]:"点这里填写中文释义",17,Color.DKGRAY));card.addView(tv(v[3],14,Color.GRAY));card.setOnClickListener(x->editWord(v));list.addView(card,new LinearLayout.LayoutParams(-1,-2));Space space=new Space(this);list.addView(space,new LinearLayout.LayoutParams(1,dp(6)));}};q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){draw.run();}public void afterTextChanged(Editable e){}});draw.run();}
  void editWord(String[] v){EditText zh=new EditText(this);zh.setText(v[2]);zh.setHint("中文释义");new AlertDialog.Builder(this).setTitle(v[1]).setMessage(v[3]+"\n来源: "+v[4]).setView(zh).setPositiveButton("保存释义",(d,w)->{db.updateZh(Long.parseLong(v[0]),zh.getText().toString());showVocab();}).setNeutralButton(v[6].equals("1")?"设为未掌握":"标记已掌握",(d,w)->{db.toggleMaster(Long.parseLong(v[0]),!v[6].equals("1"));showVocab();}).setNegativeButton("删除",(d,w)->{db.deleteWord(Long.parseLong(v[0]));showVocab();}).show();}
  void showFocus(){clear("专注计时");TextView clock=tv("25:00",58,Color.BLACK);clock.setGravity(Gravity.CENTER);content.addView(clock);EditText task=new EditText(this);task.setHint("专注内容");task.setText("读英语文章");content.addView(task);EditText min=new EditText(this);min.setInputType(2);min.setText("25");min.setHint("分钟");content.addView(min);Button start=btn(timerRun?"暂停":"开始",null);content.addView(start);start.setOnClickListener(v->{if(timerRun){timerRun=false;start.setText("继续");}else{if(timerEnd<System.currentTimeMillis())timerEnd=System.currentTimeMillis()+Math.max(1,Integer.parseInt(min.getText().toString()))*60000L;timerRun=true;start.setText("暂停");tick(clock,task.getText().toString(),start);}});content.addView(btn("重置",v->{timerRun=false;timerEnd=0;clock.setText(min.getText()+":00");start.setText("开始");}));}
  void tick(TextView c,String task,Button b){if(!timerRun)return;long left=timerEnd-System.currentTimeMillis();if(left<=0){timerRun=false;c.setText("00:00");b.setText("开始");notifyNow("专注时间到","「"+task+"」完成，休息一下吧");return;}c.setText(String.format(Locale.getDefault(),"%02d:%02d",left/60000,(left/1000)%60));handler.postDelayed(()->tick(c,task,b),500);}
  void showAlarm(){clear("定时学习提醒");TimePicker tp=new TimePicker(this);tp.setIs24HourView(true);content.addView(tp);EditText msg=new EditText(this);msg.setText("背单词");msg.setHint("提醒内容");content.addView(msg);content.addView(btn("保存每天提醒",v->{Calendar now=Calendar.getInstance(),when=Calendar.getInstance();when.set(Calendar.HOUR_OF_DAY,tp.getHour());when.set(Calendar.MINUTE,tp.getMinute());when.set(Calendar.SECOND,0);if(when.before(now))when.add(Calendar.DAY_OF_YEAR,1);Intent i=new Intent(this,AlarmReceiver.class);i.putExtra("msg",msg.getText().toString());PendingIntent p=PendingIntent.getBroadcast(this,88,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)getSystemService(ALARM_SERVICE);am.setInexactRepeating(AlarmManager.RTC_WAKEUP,when.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);Toast.makeText(this,"已设置每天 "+String.format("%02d:%02d",tp.getHour(),tp.getMinute())+" 提醒",Toast.LENGTH_LONG).show();}));content.addView(tv("说明：HarmonyOS/Android 可能为了省电延迟非精确提醒。若提醒不稳定，请在系统设置中允许 English Clock 后台运行和通知。",14,Color.DKGRAY));}
  void requestNotice(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},5);}
  void notifyNow(String title,String msg){String ch="study";NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel(ch,"学习计时",NotificationManager.IMPORTANCE_HIGH));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,ch):new Notification.Builder(this);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText(msg).setAutoCancel(true);n.notify(7,b.build());}
}
